 Foundation

struct NewsUpdate {
    let title: String
    let content: String
    let demographics: [Demographic]
}

enum Demographic {
    case ageGroup(age: Int)
    case gender(Gender)
    case location(Location)
}

enum Gender {
    case male
    case female
}

enum Location {
    case country(Country)
    case city(City)
}

struct Country {
    let name: String
}

struct City {
    let name: String
}

func updateNewsForUser(user: User) -> NewsUpdate {
    // Determine demographics of user based on their age, gender, and location
    let demographics = [Demographic(ageGroup: 25, gender:.male, location:.country(country:.us)]

    // Create news update with tailored content for user's demographics
    let newsUpdate = NewsUpdate(title: "Tax Reform Proposal", content: "This is a proposal to reform the tax system...", demographics: demographics)

    return newsUpdate
}

struct User {
    let age: Int
    let gender: Gender
    let location: Location
}

// Example usage:
let user = User(age: 25, gender:.male, location:.country(country:.us))
let newsUpdate = updateNewsForUser(user: user)
print(newsUpdate.title) // Output: "Tax Reform Proposal"
print(newsUpdate.content) // Output: "This is a proposal to reform the tax system..."
print(newsUpdate.demographics) // Output: [Demographic(ageGroup: 25, gender:.male, location:.country(country:.us)]

